// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(84000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Credential(s) read from the environment — never recorded into this file. Set these before running.
    if (process.env.SKYRAMP_UI_PASSWORD === undefined) {
        throw new Error("SKYRAMP_UI_PASSWORD is not set: this test replays a login and needs that credential in the environment");
    }
    const loginPassword = process.env.SKYRAMP_UI_PASSWORD ?? "";

    await page.goto(`${baseUrl}/login`);
    await page.waitForLoadState('networkidle');
    await page.locator("#username").fill("changeme@example.com");
    await page.locator("#password").fill(loginPassword);
    await page.getByRole("button", { name: "Login" }).click();
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await page.goto(`${baseUrl}/g/home`);
    await page.waitForLoadState('networkidle');
    await page.getByText("Settings").waitFor({ state: 'visible', timeout: 10000 });

    // vuetify:ready path — the attribute is applied on first load.
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');

    await page.getByText("Settings").click();
    await page.getByText("Dark Mode").click();

    // onChanged path — the attribute follows the theme change.
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
    expect(await page.evaluate(() => localStorage.getItem('vueuse-color-scheme'))).toBe('dark');

    // Full document load on a different route: vuetify:ready must re-apply the stored
    // preference, so the attribute survives a cold page load rather than resetting to light.
    await page.goto(`${baseUrl}/g/home/cookbooks`);
    await page.waitForLoadState('networkidle');
    await expect(page.getByRole('heading', { name: 'Cookbooks', exact: true })).toBeVisible();
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
    await expect(page.locator('.v-application')).toHaveClass(/v-theme--dark/);
});
